import { sql, type SQL } from "drizzle-orm";
import { timestamp, uuid, type AnyPgColumn } from "drizzle-orm/pg-core";

/** Shared column builders so every table stores ids and times the same way. */

/** Random UUID primary key, generated by PostgreSQL (`gen_random_uuid()`). */
export const idColumn = () => uuid("id").primaryKey().defaultRandom();

/** A point in time, always `timestamptz` (stored in UTC). */
export const timestampTz = (name: string) => timestamp(name, { withTimezone: true, mode: "date" });

export const createdAtColumn = () => timestampTz("created_at").notNull().defaultNow();

export const updatedAtColumn = () =>
  timestampTz("updated_at")
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date());

/**
 * CHECK expression limiting a text column to a fixed list of values. The values
 * are our own constants (never user input), so inlining them is safe.
 */
export function oneOf(column: AnyPgColumn, values: readonly string[]): SQL {
  const list = values.map((v) => `'${v.replace(/'/g, "''")}'`).join(", ");
  return sql`${column} in (${sql.raw(list)})`;
}
